{"script": "hits = repo.search("(?i)error", glob="**")
files = sorted({h.path for h in hits})
detail = {}
for h in hits:
    if h.path != "logs/large.log":
        detail[h.path] = detail.get(h.path, [])
        if len(detail[h.path]) < 5:
            detail[h.path].append("%d: %s" % (h.line, h.text.strip()))
r = repo.read("logs/large.log")
lines = text(r).lines()
# check for suspicious/continuation lines (not INFO heartbeat)
other = [ (i+1, l) for i,l in enumerate(lines) if not l.startswith("INFO heartbeat") ]
return {"files": files, "detail": detail, "other_lines": other}"}

